create table public.public_trust_reports(id uuid primary key default gen_random_uuid(),report_type text not null check(report_type in ('incorrect_data','fairness','privacy','accessibility','unsafe_content','other')),contact_email text,summary text not null check(char_length(summary) between 20 and 5000),preferred_language text not null default 'en' check(preferred_language in ('en','hi')),consent_to_contact boolean not null default false,reference_code text unique default('KS-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10))),status text not null default 'received' check(status in ('received','triaged','investigating','resolved','closed')),assigned_to uuid references auth.users(id),created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.public_metric_releases(id uuid primary key default gen_random_uuid(),metric_key text not null,label_en text not null,label_hi text,metric_value numeric not null,unit text not null,methodology_version text not null,period_end date not null,eligible_count integer not null,suppression_threshold integer not null default 10,published_at timestamptz,unique(metric_key,period_end,methodology_version));
create table public.public_policy_versions(id uuid primary key default gen_random_uuid(),policy_key text not null check(policy_key in ('privacy','terms','accessibility','ai_transparency','retention','outcome_methodology')),version text not null,title_en text not null,title_hi text,body_en text not null,body_hi text,status text not null default 'draft' check(status in ('draft','legal_review','approved','retired')),effective_at timestamptz,approved_by uuid references auth.users(id),unique(policy_key,version));
alter table public.public_trust_reports enable row level security;alter table public.public_metric_releases enable row level security;alter table public.public_policy_versions enable row level security;
create policy "anyone submits trust reports" on public.public_trust_reports for insert to anon,authenticated with check(true);create policy "staff manage trust reports" on public.public_trust_reports for all using(public.is_platform_staff()) with check(public.is_platform_staff());
create policy "published public metrics readable" on public.public_metric_releases for select using(published_at is not null and eligible_count>=suppression_threshold);create policy "staff manage public metrics" on public.public_metric_releases for all using(public.is_platform_staff()) with check(public.is_platform_staff());
create policy "approved policies readable" on public.public_policy_versions for select using(status='approved' and effective_at<=now());create policy "staff manage policies" on public.public_policy_versions for all using(public.is_platform_staff()) with check(public.is_platform_staff());
create index trust_reports_queue_idx on public.public_trust_reports(status,created_at);create index public_metrics_latest_idx on public.public_metric_releases(metric_key,period_end desc);
